  engine.registerFlag('surrogate_pending_revert', { type:'indefinite' });
  engine.registerFlag('surrogate_motherhood_snapshot_taken', { type:'indefinite' });
  ['surrogate_revert_this_turn','surrogate_breeder_lock_attempted']
