  if (!action || !action.trim()) return 0;
  for (const re of _ACT_PENETRATION) if (re.test(action)) return 4;
  for (const re of _ACT_ORAL)        if (re.test(action)) return 3;
  for (const re of _ACT_GROPE)       if (re.test(action)) return 2;
