  if (Math.abs(mascDelta) > 10) {
    var mascDir = mascDelta < 0 ? 'more feminine' : 'more masculine';
    beats.push({
      type: 'physical',
      text: 'Transformation progressed — body shifted ' + mascDir + '.',
      importance: 2
    });
  }

