  rs = rs || _xcwHudConfig || {};
  var stats = s.stats || {};
  var ar = parseFloat(s.arousal || 0);
  var arMax = parseInt(((rs.arousal_system || {}).max) || 100, 10);
  var arPct = _xcwArousalPct(ar, arMax);
